package com.keyforge.nativeload;
import java.sql.*;import java.util.*;
public final class NativeWorkflowImportService {private final NativeWorkflowClient client;private final NativeWorkflowRepository repo;private final int pageSize;public NativeWorkflowImportService(NativeWorkflowClient c,NativeWorkflowRepository r,int p){client=c;repo=r;pageSize=p>0?p:100;}public Result run(Connection conn)throws SQLException{repo.ensure(conn);int start=0,inserted=0,updated=0,failed=0,total=0;Set<String>keep=new LinkedHashSet<>();NativeWorkflowParser parser=new NativeWorkflowParser();while(true){List<NativeWorkflowRecord>page=parser.parse(client.fetch(start,pageSize));if(page.isEmpty())break;total+=page.size();for(NativeWorkflowRecord r:page)try{String id=NativeWorkflowRepository.id(r.sourceId);keep.add(id);if(repo.upsert(conn,r)==NativeWorkflowRepository.Outcome.INSERTED)inserted++;else updated++;}catch(Exception e){failed++;System.err.println("Native Workflow row failed (sourceId="+r.sourceId+"): "+e.getMessage());}if(page.size()<pageSize)break;start+=pageSize;}int marked=keep.isEmpty()||failed>0?0:repo.sweep(conn,keep);return new Result(total,inserted,updated,failed,marked,keep.isEmpty()||failed>0);}public static final class Result{public final int extracted,inserted,updated,failed,marked;public final boolean sweepSkipped;Result(int e,int i,int u,int f,int m,boolean ss){extracted=e;inserted=i;updated=u;failed=f;marked=m;sweepSkipped=ss;}}}
